∀ {X : Type u_1} {inst : NormedAddCommGroup X} {inst_1 : NormedSpace ℝ X} {G : ℝ → X →L[ℝ] X}
  {G_zero : G 0 = ContinuousLinearMap.id ℝ X} {G_add : ∀ (s t : ℝ), 0 ≤ s → 0 ≤ t → G (s + t) = G s ∘SL G t}
  {G_norm : ∀ (t : ℝ), 0 ≤ t → ‖G t‖ ≤ 1} {G_cont : ∀ (x : X), ContinuousOn (fun t => (G t) x) (Set.Ici 0)}
  {K : ℝ → X →L[ℝ] X →L[ℝ] X} {K_symm : ∀ (τ : ℝ) (u v : X), ((K τ) u) v = ((K τ) v) u} {CK : ℝ}
  {K_bound : ∀ (τ : ℝ), 0 < τ → τ ≤ 1 → ‖K τ‖ ≤ CK * τ ^ (-(3 / 4))}
  {K_cont : ∀ (u v : X), ContinuousOn (fun τ => ((K τ) u) v) (Set.Ioi 0)}
  {K_shift : ∀ (s τ : ℝ), 0 ≤ s → 0 < τ → ∀ (u v : X), (G s) (((K τ) u) v) = ((K (s + τ)) u) v} {G_1 : ℝ → X →L[ℝ] X}
  {G_zero_1 : G_1 0 = ContinuousLinearMap.id ℝ X} {G_add_1 : ∀ (s t : ℝ), 0 ≤ s → 0 ≤ t → G_1 (s + t) = G_1 s ∘SL G_1 t}
  {G_norm_1 : ∀ (t : ℝ), 0 ≤ t → ‖G_1 t‖ ≤ 1} {G_cont_1 : ∀ (x : X), ContinuousOn (fun t => (G_1 t) x) (Set.Ici 0)}
  {K_1 : ℝ → X →L[ℝ] X →L[ℝ] X} {K_symm_1 : ∀ (τ : ℝ) (u v : X), ((K_1 τ) u) v = ((K_1 τ) v) u} {CK_1 : ℝ}
  {K_bound_1 : ∀ (τ : ℝ), 0 < τ → τ ≤ 1 → ‖K_1 τ‖ ≤ CK_1 * τ ^ (-(3 / 4))}
  {K_cont_1 : ∀ (u v : X), ContinuousOn (fun τ => ((K_1 τ) u) v) (Set.Ioi 0)}
  {K_shift_1 : ∀ (s τ : ℝ), 0 ≤ s → 0 < τ → ∀ (u v : X), (G_1 s) (((K_1 τ) u) v) = ((K_1 (s + τ)) u) v},
  { G := G, G_zero := G_zero, G_add := G_add, G_norm := G_norm, G_cont := G_cont, K := K, K_symm := K_symm, CK := CK,
        K_bound := K_bound, K_cont := K_cont, K_shift := K_shift } =
      { G := G_1, G_zero := G_zero_1, G_add := G_add_1, G_norm := G_norm_1, G_cont := G_cont_1, K := K_1,
        K_symm := K_symm_1, CK := CK_1, K_bound := K_bound_1, K_cont := K_cont_1, K_shift := K_shift_1 } →
    G = G_1 ∧ K = K_1 ∧ CK = CK_1

∀ {X : Type} [inst : NormedAddCommGroup X] [inst_1 : NormedSpace ℝ X] (B : ℕ → X →L[ℝ] X) {C : ℝ}
  (hB : ∀ (n : ℕ), ‖B n‖ ≤ C) (hC : 0 ≤ C) (g : ↥(lp (fun x => X) ⊤)),
  ‖{ toFun := Breakdown.Periodic.SeqOps.Internal.shiftFun B hB hC, map_add' := ⋯, map_smul' := ⋯ } g‖ ≤ C * ‖g‖

∀ {X : Type} [inst : NormedAddCommGroup X] [inst_1 : NormedSpace ℝ X] (B : ℕ → X →L[ℝ] X) {C : ℝ}
  (hB : ∀ (n : ℕ), ‖B n‖ ≤ C) (hC : 0 ≤ C) (g : ↥(lp (fun x => X) ⊤)) (n : ℕ),
  ↑(Breakdown.Periodic.SeqOps.Internal.shiftFun B hB hC g) n = if n = 0 then 0 else (B (n - 1)) (↑g (n - 1))

∀ {E : Type} {inst : NormedAddCommGroup E} {inst_1 : NormedSpace ℝ E} {J : E →L[ℝ] ↥Breakdown.Freq.X} {b : ℝ}
  {field : E →ₗ[ℝ] Breakdown.Space → Breakdown.Space} {isTest : ∀ (e : E), Breakdown.IsTestField (field e)}
  {support : ∀ (e : E), tsupport (field e) ⊆ Metric.closedBall 0 b}
  {embed : ∀ (e : E), Breakdown.Freq.embedX (field e) = J e} {field_1 : E →ₗ[ℝ] Breakdown.Space → Breakdown.Space}
  {isTest_1 : ∀ (e : E), Breakdown.IsTestField (field_1 e)}
  {support_1 : ∀ (e : E), tsupport (field_1 e) ⊆ Metric.closedBall 0 b}
  {embed_1 : ∀ (e : E), Breakdown.Freq.embedX (field_1 e) = J e},
  { field := field, isTest := isTest, support := support, embed := embed } =
      { field := field_1, isTest := isTest_1, support := support_1, embed := embed_1 } →
    field = field_1

∀ {X : Type} [inst : NormedAddCommGroup X] [inst_1 : NormedSpace ℝ X] [CompleteSpace X] {T : ℝ}
  (f g : Breakdown.Piece X T) (s : ℝ),
  Breakdown.extendPiece (f + g) s = Breakdown.extendPiece f s + Breakdown.extendPiece g s
